import {evaluateShot,netSpinDegrees,targetForArena,JUMP_SPEED,GRAVITY} from './shotRules';

type Props = {config:ChallengeConfig; onComplete:(r:AttemptResult)=>void; replay?:AttemptResult; onReplayEnd?:()=>void};
