@font-face {
  font-family: Anton;
  src: url("/brand/Anton-Regular.woff2") format("woff2");
  font-display: swap;
}
@font-face {
  font-family: Source;
  src: url("/brand/SourceSansPro-Regular.woff2") format("woff2");
  font-weight: 400;
  font-display: swap;
}
@font-face {
  font-family: Source;
  src: url("/brand/SourceSansPro-Bold.woff2") format("woff2");
  font-weight: 700;
  font-display: swap;
}
:root {
  font-family: Source;
  color: #f3f1ee;
  background: #111111;
  font-synthesis: none;
  font-weight: 400;
  --red: #e4002b;
