  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 0 5.5%;
}
.brand {
  display: flex;
  gap: 18px;
  align-items: center;
  background: none;
  border: 0;
  text-align: left;
  font-family: Anton;
  font-size: 22px;
  letter-spacing: 0.2px;
  line-height: 1.1;
}
.brand img {
  width: 57px;
  height: 47px;
  object-fit: contain;
}
.brand-sub {
